(subId: string): number => {
    let current = dungeonMap.get(subId);
    if (!current) return 1;
    let depth = 1;
    while (current && current.parentId) {
      const parent = dungeonMap.get(current.parentId);
      if (parent) {
        depth++;
        current = parent;
      } else {
        break;
      }
    }
    return depth;
  }

